//! Prints `src/poseidon_params.rs`: the Poseidon round constants and MDS matrix that
//! `find_poseidon_ark_and_mds` derives, as little-endian u64 limbs.
//!
//! `cargo run -p zkapi-core --example gen_poseidon_params > crates/zkapi-core/src/poseidon_params.rs`

use ark_bn254::Fr;
use ark_crypto_primitives::sponge::poseidon::find_poseidon_ark_and_mds;
use ark_ff::PrimeField;
use zkapi_core::v2::{
    POSEIDON_FULL_ROUNDS, POSEIDON_PARTIAL_ROUNDS, POSEIDON_RATE, POSEIDON_SKIP_MATRICES,
};

fn limbs(value: &Fr) -> String {
    let words = value.into_bigint().0;
    format!(
        "[{:#018x}, {:#018x}, {:#018x}, {:#018x}]",
        words[0], words[1], words[2], words[3]
    )
}

fn main() {
    let (ark, mds) = find_poseidon_ark_and_mds::<Fr>(
        Fr::MODULUS_BIT_SIZE as u64,
        POSEIDON_RATE,
        POSEIDON_FULL_ROUNDS,
        POSEIDON_PARTIAL_ROUNDS,
        POSEIDON_SKIP_MATRICES,
    );
    let width = POSEIDON_RATE + 1;
    let rounds = (POSEIDON_FULL_ROUNDS + POSEIDON_PARTIAL_ROUNDS) as usize;
    println!("// @generated by examples/gen_poseidon_params.rs; do not edit.");
    println!("// Round constants and MDS matrix of every Poseidon hash in zkapi-core, as");
    println!("// little-endian u64 limbs of the canonical integer. A test regenerates them.");
    println!();
    println!("pub(crate) const ROUNDS: usize = {rounds};");
    println!("pub(crate) const WIDTH: usize = {width};");
    println!();
    println!("pub(crate) const ARK: [[[u64; 4]; WIDTH]; ROUNDS] = [");
    for row in &ark {
        let cells: Vec<String> = row.iter().map(limbs).collect();
        println!("    [{}],", cells.join(", "));
    }
    println!("];");
    println!();
    println!("pub(crate) const MDS: [[[u64; 4]; WIDTH]; WIDTH] = [");
    for row in &mds {
        let cells: Vec<String> = row.iter().map(limbs).collect();
        println!("    [{}],", cells.join(", "));
    }
    println!("];");
}
